// Assumed @jinx-ui/react API: Card, Stack, Text, Input, Button. Adjust names if they differ.
import { useState } from 'react';
import { Card, Stack, Text, Input, Button } from '@jinx-ui/react';

export interface RegistrationValues {
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
}

export interface RegistrationWizardProps {
  onSubmit: (values: RegistrationValues) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'];

const EMPTY: RegistrationValues = {
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY);

  const set = (key: keyof RegistrationValues) => (event: React.ChangeEvent<HTMLInputElement>) =>
    setValues((prev) => ({ ...prev, [key]: event.target.value }));

  const isLast = step === STEPS.length - 1;
  const canAdvance =
    step === 0
      ? values.email.trim() !== '' && values.phone.trim() !== ''
      : step === 1
        ? values.country.trim() !== '' && values.city.trim() !== '' && values.street.trim() !== ''
        : true;

  return (
    <Card>
      <Stack direction="column" gap="var(--jx-space-lg)">
        <Stack direction="row" gap="var(--jx-space-sm)" role="list">
          {STEPS.map((label, index) => {
            const active = index === step;
            const done = index < step;
            return (
              <Stack
                key={label}
                direction="row"
                gap="var(--jx-space-xs)"
                role="listitem"
                aria-current={active ? 'step' : undefined}
                style={{ alignItems: 'center', flex: 1 }}
              >
                <span
                  aria-hidden="true"
                  style={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: 'var(--jx-space-xl)',
                    height: 'var(--jx-space-xl)',
                    borderRadius: 'var(--jx-radius-full)',
                    border: '1px solid var(--jx-color-border)',
                    background: active || done ? 'var(--jx-color-primary)' : 'var(--jx-color-surface)',
                    color: active || done ? 'var(--jx-color-on-primary)' : 'var(--jx-color-text-muted)',
                  }}
                >
                  {index + 1}
                </span>
                <Text
                  style={{ color: active ? 'var(--jx-color-text)' : 'var(--jx-color-text-muted)' }}
                >
                  {label}
                </Text>
              </Stack>
            );
          })}
        </Stack>

        {step === 0 && (
          <Stack direction="column" gap="var(--jx-space-md)">
            <Input
              label="Email"
              type="email"
              value={values.email}
              onChange={set('email')}
            />
            <Input
              label="Телефон"
              type="tel"
              value={values.phone}
              onChange={set('phone')}
            />
          </Stack>
        )}

        {step === 1 && (
          <Stack direction="column" gap="var(--jx-space-md)">
            <Input label="Страна" value={values.country} onChange={set('country')} />
            <Input label="Город" value={values.city} onChange={set('city')} />
            <Input label="Улица, дом" value={values.street} onChange={set('street')} />
          </Stack>
        )}

        {step === 2 && (
          <Stack direction="column" gap="var(--jx-space-sm)">
            <Text>Email: {values.email}</Text>
            <Text>Телефон: {values.phone}</Text>
            <Text>Страна: {values.country}</Text>
            <Text>Город: {values.city}</Text>
            <Text>Улица, дом: {values.street}</Text>
          </Stack>
        )}

        <Stack direction="row" gap="var(--jx-space-sm)" style={{ justifyContent: 'flex-end' }}>
          <Button
            variant="secondary"
            disabled={step === 0}
            onClick={() => setStep((prev) => prev - 1)}
          >
            Назад
          </Button>
          <Button
            variant="primary"
            disabled={!canAdvance}
            onClick={() => (isLast ? onSubmit(values) : setStep((prev) => prev + 1))}
          >
            {isLast ? 'Отправить' : 'Дальше'}
          </Button>
        </Stack>
      </Stack>
    </Card>
  );
}

